// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;
    function setUp() public { c = new Proxy(); }

    function testFuzz_property(bytes memory data) public {
        Recorder rec = new Recorder();
        c.forward(address(rec), data);
        assertTrue(keccak256(rec.recordedData()) == keccak256(data));
    }
}

contract Recorder {
    bytes private data;
    fallback() external payable {
        data = msg.data;
    }
    receive() external payable {}
    function recordedData() external view returns (bytes memory) {
        return data;
    }
}
